// frontend/src/pages/FraudAnalysis.jsx

import React, { useEffect, useState } from "react";
import { fetchFraudCycles, fetchRiskLogs } from "../services/api";
import FraudExplanationPanel from "../components/FraudExplanationPanel";
import GraphView             from "../components/GraphView";
import FraudTable            from "../components/FraudTable";

export default function FraudAnalysis() {
  const [cycles,   setCycles]   = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [tab,      setTab]      = useState("explanation"); // explanation | graph | logs | temporal

  useEffect(() => {
    Promise.all([fetchFraudCycles(), fetchRiskLogs()]).then(([c, l]) => {
      setCycles(c.cycles || []);
      setRiskLogs(l);
      setLoading(false);
    });
  }, []);

  // Temporal detection: group risk_logs by seller→buyer pair, flag pairs with > 3 hits
  const temporalPairs = {};
  riskLogs.forEach((log) => {
    const key = `${log.seller_id}→${log.buyer_id}`;
    if (!temporalPairs[key]) temporalPairs[key] = { count: 0, logs: [] };
    temporalPairs[key].count++;
    temporalPairs[key].logs.push(log);
  });
  const suspiciousPairs = Object.entries(temporalPairs)
    .filter(([, v]) => v.count >= 3)
    .sort((a, b) => b[1].count - a[1].count);

  if (loading) return <p style={{ padding: "24px", color: "#94a3b8" }}>Loading fraud data...</p>;

  const tabs = [
    { key: "explanation", label: "🔍 Explanation"  },
    { key: "graph",       label: "🕸️ Network Graph" },
    { key: "logs",        label: "📋 Risk Logs"     },
    { key: "temporal",    label: "⏱️ Temporal"      },
  ];

  return (
    <div style={{ padding: "24px", background: "#0f172a", minHeight: "100vh", color: "#f1f5f9" }}>
      <h1 style={{ marginBottom: "4px" }}>🚨 Fraud Analysis Center</h1>
      <p style={{ color: "#64748b", marginBottom: "24px" }}>
        {cycles.length} fraud rings detected · {riskLogs.length} risk log entries
      </p>

      {/* Tab bar */}
      <div style={{ display: "flex", gap: "8px", marginBottom: "24px", borderBottom: "1px solid #1e293b", paddingBottom: "12px" }}>
        {tabs.map((t) => (
          <button key={t.key} onClick={() => setTab(t.key)} style={{
            padding: "8px 18px", borderRadius: "8px", border: "none",
            cursor: "pointer",
            background: tab === t.key ? "#3b82f6" : "#1e293b",
            color: "#f1f5f9", fontWeight: tab === t.key ? "bold" : "normal"
          }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* Tab: Explanation */}
      {tab === "explanation" && <FraudExplanationPanel cycles={cycles} />}

      {/* Tab: Network Graph */}
      {tab === "graph" && (
        cycles.length > 0
          ? <GraphView cycles={cycles} />
          : <p>No fraud cycles to visualize.</p>
      )}

      {/* Tab: Risk Logs */}
      {tab === "logs" && <FraudTable logs={riskLogs} />}

      {/* Tab: Temporal Detection */}
      {tab === "temporal" && (
        <div>
          <h2>⏱️ Rapid Repeated Trades (Temporal Fraud)</h2>
          <p style={{ color: "#64748b", marginBottom: "16px" }}>
            Pairs that appear 3+ times in the risk log — indicates coordinated repeated trading.
          </p>
          {suspiciousPairs.length === 0 && <p>No temporal patterns detected yet.</p>}
          {suspiciousPairs.map(([pair, data]) => (
            <div key={pair} style={{
              background: "#1e293b", borderRadius: "10px", padding: "16px",
              marginBottom: "12px", borderLeft: "4px solid #f97316"
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3 style={{ margin: 0 }}>🔁 {pair}</h3>
                <span style={{ background: "#f97316", padding: "2px 10px", borderRadius: "12px", fontSize: "0.8rem" }}>
                  {data.count} occurrences
                </span>
              </div>
              <p style={{ color: "#94a3b8", fontSize: "0.85rem", marginTop: "8px" }}>
                Avg risk score: {Math.round(data.logs.reduce((s, l) => s + l.risk_score, 0) / data.count)}
              </p>
              <div style={{ marginTop: "8px" }}>
                {data.logs.slice(0, 3).map((l) => (
                  <div key={l.risk_id} style={{ fontSize: "0.8rem", color: "#64748b", marginBottom: "4px" }}>
                    Trade #{l.trade_id} — Score: {l.risk_score} — {new Date(l.detected_at).toLocaleString()}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
